#include <vector>
// Outro problema: devolver a soma dos quadrados dos elementos.
// Ilustra apenas o esqueleto da varredura com acumulador.
long somaDosQuadrados(const std::vector<int>& v) {
    long acumulado = 0;              // ponto de partida
    for (std::size_t i = 0; i < v.size(); ++i) {
        long termo = v[i];           // valor da posicao atual
        acumulado += termo * termo;  // regra de atualizacao
    }
    return acumulado;
}
