fn contar_exclamacoes(frase: &str) -> usize {
    let mut total = 0;
    for c in frase.chars() {
        if c == '!' {
            total += 1;
        }
    }
    total
}

// versão com adaptadores
fn contar_exclamacoes2(frase: &str) -> usize {
    frase.chars().filter(|c| *c == '!').count()
}

